/* Enforce display hidden override rule */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #0f172a;
  --card-bg: #1e293b;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --accent: #38bdf8;
  --accent-hover: #0284c7;
  --danger: #f43f5e;
  --success: #10b981;
  --focus-ring: #38bdf8;
  --border-radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background-color: var(--bg-color);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-container {
  background-color: var(--card-bg);
  border-radius: var(--border-radius);
  padding: 24px;
  width: 100%;
  max-width: 440px;
  min-width: 320px;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  gap: 20px;
  text-align: center;
}

.game-header h1 {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 4px;
  color: var(--text-main);
}

.subtitle {
  font-size: 1rem;
  color: var(--text-muted);
}

.scoreboard {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.score-pill {
  background-color: rgba(15, 23, 42, 0.6);
  padding: 10px 14px;
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  border: 1px solid rgba(255, 255, 255, 0.05);
}

.score-label {
  font-size: 0.875rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.score-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent);
}

.target-display {
  background-color: rgba(15, 23, 42, 0.8);
  border: 1px dashed var(--text-muted);
  border-radius: var(--border-radius);
  padding: 16px;
}

.target-label {
  display: block;
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: 4px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.rgb-code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: var(--text-main);
}

.swatch-group {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.swatch {
  aspect-ratio: 1 / 1;
  border: 3px solid transparent;
  border-radius: var(--border-radius);
  cursor: pointer;
  transition: transform 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
  outline: none;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.3);
}

.swatch:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 8px 12px -2px rgba(0, 0, 0, 0.4);
}

.swatch:focus-visible {
  border-color: var(--focus-ring);
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.4);
}

.swatch:active:not(:disabled) {
  transform: translateY(0);
}

.swatch:disabled {
  cursor: default;
  opacity: 0.85;
}

.message-banner {
  padding: 10px 14px;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
}

.message-banner.success {
  background-color: rgba(16, 185, 129, 0.15);
  color: var(--success);
  border: 1px solid var(--success);
}

.message-banner.danger {
  background-color: rgba(244, 63, 94, 0.15);
  color: var(--danger);
  border: 1px solid var(--danger);
}

.btn {
  background-color: var(--accent);
  color: #0f172a;
  border: none;
  border-radius: 8px;
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  width: 100%;
  transition: background-color 0.15s ease, transform 0.1s ease;
  outline: none;
}

.btn:hover {
  background-color: var(--accent-hover);
  color: #ffffff;
}

.btn:focus-visible {
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.5);
}

.btn:active {
  transform: scale(0.98);
}

document.addEventListener('DOMContentLoaded', () => {
  let currentStreak = 0;
  let bestStreak = 0;
  let targetColor = { r: 0, g: 0, b: 0 };
  let correctIndex = 0;
  let isRoundOver = false;

  const currentStreakEl = document.getElementById('current-streak');
  const bestStreakEl = document.getElementById('best-streak');
  const rgbDisplayEl = document.getElementById('rgb-display');
  const messageEl = document.getElementById('message');
  const actionBtn = document.getElementById('action-btn');
  const swatches = [
    document.getElementById('swatch-0'),
    document.getElementById('swatch-1'),
    document.getElementById('swatch-2')
  ];

  const STORAGE_KEY = 'pixel_color_guesser_best';
  const savedBest = localStorage.getItem(STORAGE_KEY);
  if (savedBest !== null) {
    bestStreak = parseInt(savedBest, 10) || 0;
    bestStreakEl.textContent = bestStreak;
  }

  function getRandomChannel() {
    return Math.floor(Math.random() * 256);
  }

  function generateRandomColor() {
    return {
      r: getRandomChannel(),
      g: getRandomChannel(),
      b: getRandomChannel()
    };
  }

  function colorToString(c) {
    return `rgb(${c.r}, ${c.g}, ${c.b})`;
  }

  function generateDistractor(target) {
    // Ensure the distractor color has distinct visual difference
    let color;
    let diff;
    do {
      color = generateRandomColor();
      diff = Math.abs(color.r - target.r) + Math.abs(color.g - target.g) + Math.abs(color.b - target.b);
    } while (diff < 75);
    return color;
  }

  function setupRound() {
    isRoundOver = false;
    targetColor = generateRandomColor();
    correctIndex = Math.floor(Math.random() * 3);

    rgbDisplayEl.textContent = colorToString(targetColor);
    messageEl.hidden = true;
    messageEl.className = 'message-banner';
    messageEl.textContent = '';
    actionBtn.textContent = 'Skip / New Color';

    swatches.forEach((swatch, idx) => {
      swatch.disabled = false;
      let color;
      if (idx === correctIndex) {
        color = targetColor;
      } else {
        color = generateDistractor(targetColor);
      }
      swatch.style.backgroundColor = colorToString(color);
      swatch.setAttribute('aria-label', `Color option ${idx + 1}`);
    });
  }

  function handleGuess(selectedIndex) {
    if (isRoundOver) return;

    if (selectedIndex === correctIndex) {
      currentStreak += 1;
      if (currentStreak > bestStreak) {
        bestStreak = currentStreak;
        localStorage.setItem(STORAGE_KEY, bestStreak.toString());
        bestStreakEl.textContent = bestStreak;
      }
      currentStreakEl.textContent = currentStreak;

      messageEl.textContent = 'Correct! Great match.';
      messageEl.className = 'message-banner success';
      messageEl.hidden = false;

      swatches.forEach(swatch => {
        swatch.disabled = true;
      });

      setTimeout(() => {
        setupRound();
      }, 900);
    } else {
      isRoundOver = true;
      currentStreak = 0;
      currentStreakEl.textContent = currentStreak;

      messageEl.textContent = 'Game Over! Wrong swatch chosen.';
      messageEl.className = 'message-banner danger';
      messageEl.hidden = false;

      swatches.forEach((swatch, idx) => {
        swatch.disabled = true;
        if (idx === correctIndex) {
          swatch.style.outline = '3px solid var(--success)';
        }
      });
      actionBtn.textContent = 'Play Again';
    }
  }

  swatches.forEach((swatch, index) => {
    swatch.addEventListener('click', () => {
      handleGuess(index);
    });
  });

  actionBtn.addEventListener('click', () => {
    if (isRoundOver) {
      currentStreak = 0;
      currentStreakEl.textContent = currentStreak;
    }
    swatches.forEach(swatch => {
      swatch.style.outline = 'none';
    });
    setupRound();
  });

  setupRound();
});
